pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, address target, uint amount, bool callWithdrawAll) public {
        // Ensure sender is not the owner (to avoid onlyOwner restrictions for sendMoney)
        vm.assume(sender != c.owner());
        // Give sender some ether to send
        vm.deal(sender, amount);
        // Bound amount to avoid overflow issues
        amount = bound(amount, 1, 1e18);

        // Simulate: owner sends money to target via sendMoney
        vm.prank(c.owner());
        c.sendMoney(target, amount);

        // Conditionally call withdrawAll
        if (callWithdrawAll) {
            vm.prank(c.owner());
            c.withdrawAll();
        }

        // General rule: After any sequence ending with sendMoney, the contract balance is either the sent amount (if withdrawAll was not called) or zero (if called).
        // But since withdrawAll deletes the call to withdraw(...), the buggy version will never reduce balance.
        // So we assert that after calling withdrawAll, balance must be zero only if the reference implementation correctly withdraws.
        // Here we use a simpler invariant: The amount held by the contract is always >= 0 (trivial).
        // Actually, we need a rule that distinguishes the bug: The bug causes contract balance to always grow after sendMoney, never decrease.
        // So rule: After sendMoney, if withdrawAll is called, balance should be 0 (in reference) but in mutant it remains non-zero.
        // However, to make it a general rule, we assert: When callWithdrawAll is true, contract.balance == 0.
        assertTrue(!callWithdrawAll || address(c).balance == 0);
    }
}

