pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Restrict to non-zero value that won't cause issues
        vm.assume(value > 0 && value <= 100 ether);
        // Record balance before sendMoney
        uint256 balanceBefore = address(c).balance;
        // Get the owner (deployer) so we can send ETH to the contract first
        address owner = c.owner();
        // Fund the contract with some initial ETH
        vm.deal(address(c), 10 ether);
        balanceBefore = address(c).balance;
        // Call sendMoney as owner
        vm.prank(owner);
        c.sendMoney(target, value);
        uint256 balanceAfter = address(c).balance;
        // The rule: the balance should have decreased by exactly value (but due to the bug, it won't if withdrawAll is called after and fails to reduce)
        // Actually we want to check that the balance is never reduced by withdrawAll because the bug removes that call.
        // Simpler: After sendMoney, balance decreases by value (assuming target is payable).
        // But the bug is in withdrawAll, so we shouldn't call it here. The difference is that in P (reference), withdrawAll reduces balance; in M, it does nothing.
        // Since we only drive through sendMoney, we can't directly test withdrawAll. Let's restructure to test the full flow:
        // Make a call that triggers withdrawAll after sendMoney.
        // Actually, the difference is: after sendMoney, the state variable 'depositsCount' might differ? No, the problem states withdrawAll differs.
        // The only way to observe withdrawAll output is to call it. Let's call withdrawAll after sendMoney and check that balance is zero in reference but not in mutant.
        // But the bug is that withdrawAll does nothing, so after sendMoney (which sends ETH to target), if we then call withdrawAll, the balance should go to zero in reference, but in mutant it stays same.
        // This test will pass on reference and fail on mutant.
        // So we do:
        uint256 balAfterSend = address(c).balance;
        vm.prank(owner);
        c.withdrawAll();
        uint256 balAfterWithdraw = address(c).balance;
        assertTrue(balAfterWithdraw == 0, "After withdrawAll, balance should be 0");
    }
}

